"""autoedit engine audio (generated by regen_engine.py from a production audio.py).
premix(out_wav, shots=None) -> dict ; master(in_wav, out_wav) -> dict
Timing = compiled events in timeline.json; beds / SFX / raw levels = its audio plan (video.json music, sfx; raw lufs, bed_db, bleeps).
48 kHz stereo float32. Length = total_frames * 1600 samples exactly.
CLI: python -I -X utf8 build/audio.py <out_dir>   (premix.wav + master.wav, prints LUFS / TP / bed-under-VO LU)"""
import json, os, re, subprocess, sys
import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE)
import timeline as TLM  # noqa: E402  (compiled timeline.json: events + audio plan)
P = TLM.P
SR, FPS = 48000, 30
SPF = SR // FPS                                    # 1600 samples per frame
VO_LUFS, RAW_LUFS, RAW_TAIL_LUFS = -16.0, -17.0, -24.0
BED_UNDER_VO = 17.0                                # LU under VO (owner range 15-20, never < 12)
BED_REL = {'vo': 0.0, 'raw': -6.0, 'hold': 6.0, 'card': 6.0, 'list': 6.0, 'dip': 6.0}
SFX_UNDER_VO = 14.0
XFADE, FADE_IN, FADE_OUT = 6.0, 1.5, 2.5
RAW_FADE_F = 5
BLEEP_LUFS = -18.0
MASTER_LUFS, MASTER_TP = -16.0, -1.5
FF = 'ffmpeg'


# ---------------------------------------------------------------- io / measure
def load(path, t0=None, dur=None):
    cmd = [FF, '-v', 'error']
    if t0 is not None: cmd += ['-ss', '%.4f' % t0]
    if dur is not None: cmd += ['-t', '%.4f' % dur]
    cmd += ['-i', path, '-vn', '-ac', '2', '-ar', str(SR), '-f', 'f32le', '-']
    a = np.frombuffer(subprocess.run(cmd, capture_output=True, check=True).stdout, np.float32)
    return a.reshape(-1, 2).copy()


def save(path, a):
    os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    subprocess.run([FF, '-v', 'error', '-y', '-f', 'f32le', '-ar', str(SR), '-ac', '2', '-i', '-', '-c:a', 'pcm_f32le', path],
                   input=np.ascontiguousarray(a, np.float32).tobytes(), check=True)


def measure(src):
    """(integrated LUFS, true peak dBTP) via ffmpeg ebur128. src = path or (n,2) array."""
    cmd = [FF, '-hide_banner', '-nostats']
    if isinstance(src, str): cmd += ['-i', src]; inp = None
    else: cmd += ['-f', 'f32le', '-ar', str(SR), '-ac', '2', '-i', '-']; inp = np.ascontiguousarray(src, np.float32).tobytes()
    err = subprocess.run(cmd + ['-af', 'ebur128=peak=true', '-f', 'null', '-'], input=inp, capture_output=True).stderr.decode('utf-8', 'replace')
    s = err[err.rfind('Summary:'):]
    i = re.search(r'I:\s+(-?[\d.]+|-inf) LUFS', s); tp = re.search(r'Peak:\s+(-?[\d.]+|-inf) dBFS', s)
    f = lambda m: -70.0 if (not m or 'inf' in m.group(1)) else float(m.group(1))
    return f(i), f(tp)


db = lambda x: 10 ** (x / 20.0)


# ---------------------------------------------------------------- plan
def ts(s):
    m, x = s.split(':'); return int(m) * 60 + float(x)


def segments():
    """Audio plan rows from the compiled events (vo / raw / hold / card / dip) + list shots, in frame order."""
    rows = []
    for e in TLM.events():
        k = e['type']; f0 = e['f0']
        r = {'name': e.get('take') or e.get('name') or k, 'kind': k, 'f0': f0, 'f1': f0 + e['nf'], 'bed_db': e.get('bed_db')}
        if k == 'raw':
            r.update(id=e['name'], src=e['src'], w0=e['a'], w1=e['b'], lufs=e.get('lufs'), bleeps=e.get('bleeps', []))
        rows.append(r)
    for s in TLM.timeline():
        if s['kind'] == 'list': rows.append({'name': s['name'], 'kind': 'list', 'f0': s['f0'], 'f1': s['f0'] + s['nf'], 'bed_db': None})
    rows.sort(key=lambda r: r['f0'])
    return rows


def total_frames(shots, segs):
    if shots:
        ends = []
        for s in shots:
            g = s.get if isinstance(s, dict) else (lambda k, d=None, s=s: getattr(s, k, d))
            e = g('f1') or g('end')
            if e is None and g('dur') is not None: e = (g('f0') or g('start') or 0) + g('dur')
            if e is not None: ends.append(int(e))
        if ends: return max(ends)
    return max(s['f1'] for s in segs)


# ---------------------------------------------------------------- premix
def ramp(n, up=True):
    r = np.linspace(0, 1, max(n, 1), dtype=np.float32); return r if up else r[::-1]


def add(mix, x, s0):
    s0 = int(s0); a, b = max(s0, 0), min(s0 + len(x), len(mix))
    if b > a: mix[a:b] += x[a - s0:b - s0]


def smooth_frames(g, win):
    k = np.ones(win, np.float32) / win; p = win // 2
    return np.convolve(np.pad(g, (p, win - 1 - p), mode='edge'), k, mode='valid')


def premix(out_wav, shots=None):
    segs = segments()
    if shots is None:
        try:
            shots = TLM.timeline()
        except Exception as e:
            print('audio: timeline() unavailable (%s) -> plan length' % e.__class__.__name__); shots = None
    NF = total_frames(shots, segs); N = NF * SPF
    AP = TLM.audio_plan()
    vo = np.zeros((N, 2), np.float32); raw = np.zeros((N, 2), np.float32)
    vo_on = np.zeros(NF, bool); fkind = np.array(['vo'] * NF, dtype=object); duck = np.zeros(NF, np.float32)
    for s in segs:
        fkind[s['f0']:s['f1']] = s['kind']
        if s.get('bed_db'): duck[s['f0']:s['f1']] = np.minimum(duck[s['f0']:s['f1']], s['bed_db'])
    # VO: level only
    for s in (x for x in segs if x['kind'] == 'vo'):
        p = os.path.join(P, 'vo', 'raw', s['name'] + '.wav'); x = load(p)
        L, _ = measure(x);   # stereo-duplicated take (mono file would read 3 dB low)
        x *= db(VO_LUFS - L)
        add(vo, x, s['f0'] * SPF); vo_on[s['f0']:min(NF, s['f0'] + -(-len(x) // SPF))] = True
        fkind[s['f0']:min(NF, s['f0'] + -(-len(x) // SPF))] = 'vo'
    # raws: own audio, fades, bleeps, tail ducked under next VO
    for s in (x for x in segs if x['kind'] == 'raw'):
        d = s['w1'] - s['w0']; x = load(os.path.join(P, 'sources', s['src'] + '.mp4'), s['w0'], d)
        n = (s['f1'] - s['f0']) * SPF; x = np.pad(x, ((0, max(0, n - len(x))), (0, 0)))[:n]
        tgt = s['lufs'] if s.get('lufs') is not None else RAW_LUFS; L, _ = measure(x); x *= db(tgt - L)
        for b in s['bleeps']:                              # source seconds [a, b]
            if b[1] <= s['w0'] or b[0] >= s['w1']: continue
            a0, a1 = int((max(b[0], s['w0']) - s['w0']) * SR), int((min(b[1], s['w1']) - s['w0']) * SR)
            t = np.arange(a1 - a0) / SR; tone = np.sin(2 * np.pi * 1000 * t).astype(np.float32) * db(BLEEP_LUFS + 0.691)
            e = min(96, (a1 - a0) // 4); env = np.ones(a1 - a0, np.float32); env[:e] = ramp(e); env[-e:] = ramp(e, False)
            x[a0:a1] = (tone * env)[:, None]   # tone replaces raw (2 ms edges)
        g = np.ones(n, np.float32); fs = RAW_FADE_F * SPF
        g[:fs] = ramp(fs); g[-fs:] *= ramp(fs, False)
        nxt = [v for v in segs if v['kind'] == 'vo' and s['f0'] < v['f0'] < s['f1']]
        if nxt:                                            # tail under the next VO -> -24 LUFS-eq, 6 f ramp
            k0 = (nxt[0]['f0'] - s['f0']) * SPF; dg = db(min(0.0, RAW_TAIL_LUFS - tgt)); r6 = 6 * SPF
            tail = np.full(n - k0, dg, np.float32); m = min(r6, len(tail)); tail[:m] = 1 + (dg - 1) * ramp(m)
            g[k0:] *= tail
        add(raw, x * g[:, None], s['f0'] * SPF)
    # beds: one per case; 6 s equal-power crossfades centred on card starts
    cards = [s['f0'] for s in segs if s['kind'] == 'card']
    beds = [(b['file'], b['f0'], NF if b['f1'] is None else b['f1'], b.get('offset')) for b in AP['beds']]   # video.json music
    xf = int(XFADE * SR); bed_parts = []
    for i, (fn, fa, fb, off) in enumerate(beds):
        sa = 0 if i == 0 else fa * SPF - xf // 2; sb = N if fb == NF else fb * SPF + xf // 2
        path = os.path.join(P, 'assets', 'music', fn)
        if off is None:                                    # offset null: track end = video end
            dur = float(subprocess.run(['ffprobe', '-v', 'error', '-show_entries', 'format=duration', '-of', 'csv=p=0', path],
                                       capture_output=True, text=True).stdout); off = max(0.0, dur - (sb - sa) / SR)
        x = load(path, off, (sb - sa) / SR); x = np.pad(x, ((0, max(0, sb - sa - len(x))), (0, 0)))[:sb - sa]
        L, _ = measure(x); x *= db(VO_LUFS - BED_UNDER_VO - L)
        env = np.ones(len(x), np.float32)
        if i > 0: env[:xf] = np.sqrt(ramp(xf))
        if fb != NF: env[-xf:] = np.sqrt(ramp(xf, False))
        bed_parts.append([x * env[:, None], sa, fa, fb, off, fn])
    # bed level envelope (frame rate): duck early / release late, smoothed
    gdb = np.array([BED_REL.get(k, 0.0) for k in fkind], np.float32); gdb[vo_on] = 0.0; gdb += duck
    early = np.array([gdb[max(0, i - 8):i + 9].min() for i in range(NF)], np.float32)
    gdb = smooth_frames(early, 12)[:NF]
    genv = np.interp(np.arange(N) / SPF, np.arange(NF), db(gdb)).astype(np.float32)
    fi, fo = int(FADE_IN * SR), int(FADE_OUT * SR); genv[:fi] *= ramp(fi); genv[-fo:] *= ramp(fo, False)

    def bed_mix(parts):
        b = np.zeros((N, 2), np.float32)
        for x, sa, *_ in parts: add(b, x, sa)
        return b * genv[:, None]
    # calibrate each bed: integrated bed-under-VO (VO-active frames of that case) = BED_UNDER_VO LU
    vmask = np.repeat(vo_on, SPF)
    bed = bed_mix(bed_parts); report = []
    for p in bed_parts:
        x, sa, fa, fb = p[:4]; m = vmask.copy(); m[:max(0, fa * SPF)] = False; m[fb * SPF:] = False
        if m.sum() < SR: continue
        lb, _ = measure(bed[m]); lv, _ = measure(vo[m]); corr = (lv - BED_UNDER_VO) - lb
        p[0] = x * db(corr); report.append((p[5], round(p[4], 2), round(lv - lb, 1), round(corr, 1)))
    bed = bed_mix(bed_parts)
    # SFX: boom at card starts +4 f, whoosh centred on dips; ~14 dB under VO
    sfx = np.zeros((N, 2), np.float32)
    SX = AP.get('sfx', {})
    for fn, starts, centre in ((SX.get('card'), [c + 4 for c in cards], False),
                               (SX.get('dip'), [(s['f0'] + s['f1']) // 2 for s in segs if s['kind'] == 'dip'], True)):
        if not fn: continue
        p = os.path.join(P, 'assets', 'sfx', fn); x = load(p); L, _ = measure(x); x *= db(VO_LUFS - SFX_UNDER_VO - L)
        for f in starts: add(sfx, x, f * SPF - (len(x) // 2 if centre else 0))
    # floor: where the whole mix would sit below -46 dBFS (400 ms RMS), lift the bed (<= +15 dB, smoothed); end fade exempt
    rest = vo + raw + sfx
    def frms(a):
        return 10 * np.log10((a.astype(np.float64) ** 2).mean(1).reshape(NF, SPF).mean(1) + 1e-12)
    lvl = smooth_frames(frms(rest + bed).astype(np.float32), 12)[:NF]; bl = smooth_frames(frms(bed).astype(np.float32), 12)[:NF]
    need = np.clip(-46.0 - lvl, 0, 15).astype(np.float32); need[bl < -80] = 0; need[-int((FADE_OUT + 0.5) * FPS):] = 0
    need = smooth_frames(np.array([need[max(0, i - 15):i + 16].max() for i in range(NF)], np.float32), 20)[:NF]
    if need.max() > 0:
        bed *= np.interp(np.arange(N) / SPF, np.arange(NF), db(need)).astype(np.float32)[:, None]
        print('audio: bed floor lift max %.1f dB over %.1f s' % (need.max(), (need > 0.5).sum() / FPS))
    mix = rest + bed; del rest
    lus = []                                              # bed-under-VO LU per case, after the floor lift
    for p in bed_parts:
        m = vmask.copy(); m[:max(0, p[2] * SPF)] = False; m[p[3] * SPF:] = False
        if m.sum() >= SR: lus.append(round(measure(vo[m])[0] - measure(bed[m])[0], 1))
    if lus and min(lus) < 12: print('audio: WARN bed under VO < 12 LU', lus)
    assert len(mix) == NF * SPF
    # never silent: 400 ms RMS below -50 dBFS for >= 1.2 s (end fade excluded)
    w = SR * 2 // 5; e = (mix ** 2).mean(1)[: (N - fo) // w * w].reshape(-1, w).mean(1)
    low = 10 * np.log10(e + 1e-12) < -50; run = best = 0
    for v in low: run = run + 1 if v else 0; best = max(best, run)
    save(out_wav, mix)
    st = {'frames': NF, 'samples': len(mix), 'seconds': NF / FPS, 'bed_under_vo_LU': lus, 'bed_cal': report,
          'longest_quiet_s': round(best * 0.4, 1)}
    print('premix: %d f = %.3f s, %d samples | bed under VO LU per case %s | longest <-50 dB run %.1f s'
          % (NF, NF / FPS, len(mix), lus, st['longest_quiet_s']))
    return st


# ---------------------------------------------------------------- master
def master(in_wav, out_wav, vo_words=None):
    """Linear gain to -16 LUFS, alimiter (latency=1, 4x oversampled) to <= -1.5 dBTP.
    If > 6 dB of limiting would be needed, clip-gain the loudest word-length peaks first (300 ms regions, 20 ms ramps)."""
    x = load(in_wav); n = len(x)
    L, tp = measure(x); g = MASTER_LUFS - L; x *= db(g)
    lim = MASTER_TP - 0.3
    pk = 20 * np.log10(np.abs(x).max() + 1e-12); clipped = 0
    if pk - lim > 6.0:                                    # clip-gain loudest words so limiter works <= 6 dB
        thr = db(lim + 6.0); a = np.abs(x).max(1); hop = SR * 3 // 10
        for i in np.nonzero(a.reshape(-1)[: n // hop * hop].reshape(-1, hop).max(1) > thr)[0]:
            s0, s1 = i * hop, (i + 1) * hop; gg = thr / a[s0:s1].max(); r = SR // 50
            env = np.full(s1 - s0 + 2 * r, gg, np.float32); env[:r] = 1 + (gg - 1) * ramp(r); env[-r:] = 1 + (gg - 1) * ramp(r, False)
            lo = max(0, s0 - r); env = env[lo - (s0 - r):][: min(n, s1 + r) - lo]; x[lo:lo + len(env)] *= env[:, None]; clipped += 1
        L2, _ = measure(x); x *= db(MASTER_LUFS - L2)
    tmp = out_wav + '.pre.wav'; pre = 0.0
    for attempt in range(6):                              # limiter TP <= -1.5 and integrated within 0.2 LU of -16
        save(tmp, x * db(pre))
        af = ('aresample=192000,alimiter=limit=%.5f:attack=5:release=60:latency=1:level=0,aresample=%d' % (db(lim), SR))
        subprocess.run([FF, '-v', 'error', '-y', '-i', tmp, '-af', af, '-c:a', 'pcm_f32le', '-ar', str(SR), '-ac', '2', out_wav], check=True)
        y = load(out_wav); y = np.pad(y, ((0, max(0, n - len(y))), (0, 0)))[:n]
        Lo, tpo = measure(y)
        ok_tp, ok_l = tpo <= MASTER_TP, abs(Lo - MASTER_LUFS) <= 0.2
        if ok_tp and ok_l: break
        if not ok_tp: lim -= (tpo - MASTER_TP) + 0.1
        if not ok_l: pre += MASTER_LUFS - Lo
    g += pre
    save(out_wav, y); os.remove(tmp)
    st = {'in_LUFS': L, 'in_TP': tp, 'gain_dB': round(g, 2), 'limit_dB': round(lim, 2), 'clip_gained_regions': clipped,
          'LUFS': Lo, 'TP': tpo, 'samples': len(y)}
    print('master: in %.1f LUFS / %.1f dBTP -> gain %+.2f dB, limiter %.2f dB, %d clip-gain regions -> %.1f LUFS, %.1f dBTP, %d samples'
          % (L, tp, g, lim, clipped, Lo, tpo, len(y)))
    return st


if __name__ == '__main__':
    out = sys.argv[1] if len(sys.argv) > 1 else os.path.join(P, 'renders', 'audio')
    st = premix(os.path.join(out, 'premix.wav'))
    print('bed cal (bed, offset s, LU before, corr dB):', st['bed_cal'])
    ms = master(os.path.join(out, 'premix.wav'), os.path.join(out, 'master.wav'))
    print('RESULT LUFS %.1f | TP %.1f dBTP | bed-under-VO LU %s | length %d samples = %d f' % (
        ms['LUFS'], ms['TP'], st['bed_under_vo_LU'], ms['samples'], ms['samples'] // SPF))
